m29,b29,r29,step=regression(29,ulcer);mend=(8.2-14.1)/56000;bend=14.1-mend*4000
add(29,('소득달러·100명당 평생 궤양률 자료 '+str(ulcer)+'에 대해(a)산점도와 선형성,(b)양끝점 직선,(c)회귀선,(d)25000달러,(e)80000달러의 회귀 예측,(f)200000달러 적용 타당성을 구하라.','For the(income in dollars,lifetime ulcers per100 people) data '+str(ulcer)+', find(a) scatter plot and linear suitability,(b) endpoint line,(c) regression line,(d) prediction at$25000,(e) at$80000,(f) suitability at$200000.'),[('자료는 대체로 감소하는 직선 근처에 있으므로 관측 범위 안에서 선형 근사가 가능하다.','The points lie near a decreasing line, supporting a linear approximation within the observed range.'),(d(f'L(x)={mend:.10f}x+{bend:.8f}'),d(f'L(x)={mend:.10f}x+{bend:.8f}')),step,('80000달러는 자료 밖 외삽이며200000달러에서는 음수 비율이 나와 모형이 부적절하다.','The$80000 value is an extrapolation. At$200000 the predicted rate becomes negative, making the model inappropriate.')],('(b)'+m(f'L(x)={mend:.10f}x+{bend:.8f}')+'; (c)'+m(f'R(x)={m29:.10f}x+{b29:.8f}')+f'; (d){m29*25000+b29:.3f}/100명; (e){m29*80000+b29:.3f}%; (f)부적절, 예측={m29*200000+b29:.3f}%.','(b)'+m(f'L(x)={mend:.10f}x+{bend:.8f}')+'; (c)'+m(f'R(x)={m29:.10f}x+{b29:.8f}')+f'; (d){m29*25000+b29:.3f} per100; (e){m29*80000+b29:.3f}%; (f)inappropriate, prediction={m29*200000+b29:.3f}%.'),('반올림 전 계수에서 잔차의 합과 입력가중 잔차의 합이 모두0이다. '+f'R²={r29:.5f}.','Before rounding, residuals and input-weighted residuals each sum to zero. '+f'R²={r29:.5f}.'),list('abcdef'))
regfig(29,ulcer,lambda z:m29*z+b29,'Ulcer rates: regression blue; endpoint line red','income $','per100',extra=[[(4000,14.1),(60000,8.2)]])
