add(30,('실험의 석면 노출량(fibers/mL)·폐종양 발생률(%) 자료 '+str(asbestos)+'에 대해(a)회귀선,(b)산점도와 적합성,(c)y절편의 의미를 구하라.','For experimental asbestos exposure(fibers/mL) and lung-tumor percentage data '+str(asbestos)+', find(a) a regression line,(b) a scatter plot and fit assessment,(c) the meaning of the intercept.'),[step,('산점도는 상당한 산포가 있지만 대체로 증가하는 직선을 따른다. 절편은 노출량0에서의 예측 발생률이다.','Despite noticeable scatter, the points show an approximately increasing linear trend. The intercept predicts the percentage at zero exposure.'),('절편은 약0.305%로, 노출이 없어도 발생하는 배경 종양률의 모형 추정치이다. 관측 최저 노출은50이므로0에서의 값은 약한 외삽이다.','The intercept is about0.305%, a model estimate of background tumor incidence without exposure. Since the smallest observed exposure is50, the value at zero is a short extrapolation.')],('(a)'+m(f'y={m30:.8f}x{b30:+.8f}')+f'. (b)관측 범위의 대략적 모형,R²={r30:.4f}. (c)무노출 예측{b30:.3f}%의 배경 발생률 추정이다.','(a)'+m(f'y={m30:.8f}x{b30:+.8f}')+f'. (b)An approximate model over the observed range,R²={r30:.4f}. (c)Its zero-exposure prediction is{b30:.3f}%, an estimate of background incidence.'),('원자료9쌍을 사용했고 정규방정식의 두 잔차 합이0임을 확인했다.','Used all9 pairs and verified both normal-equation residual sums are zero.'),list('abc'))
regfig(30,asbestos,lambda z:m30*z+b30,'Exposure and tumor percentage','fibers/mL','%')
femur=[(50.1,178.5),(48.3,173.6),(45.2,164.8),(44.7,163.7),(44.5,168.3),(42.7,165),(39.5,155.4),(38,155.8)]
m31,b31,r31,step=regression(31,femur)
add(31,('남성8명의 대퇴골 길이·키(cm) 자료 '+str(femur)+'로(a)산점도,(b)회귀선과 그래프,(c)대퇴골53 cm의 예상 키를 구하라.','Using the8 male(femur length,height) pairs in cm '+str(femur)+', find(a) a scatter plot,(b) the regression line and graph,(c) predicted height for a53-cm femur.'),[step,('L=53을 회귀식에 대입한다. 관측 최대50.1 cm보다 크므로 외삽이다.','Substitute L=53 into the regression line. This extrapolates beyond the observed maximum50.1 cm.')],('(b)'+m(f'H(L)={m31:.8f}L+{b31:.8f}')+f'; (c)약{m31*53+b31:.2f} cm.','(b)'+m(f'H(L)={m31:.8f}L+{b31:.8f}')+f'; (c)approximately{m31*53+b31:.2f} cm.'),('최소제곱 정규방정식의 잔차합0을 확인했다. '+f'R²={r31:.5f}. 이 표본에 적합한 모형이다.','Verified zero residual sums in the least-squares normal equations. '+f'R²={r31:.5f}. The model is fitted to this sample.'),list('abc'))
regfig(31,femur,lambda z:m31*z+b31,'Femur length and height','femur cm','height cm')
for n,base,data,ask,desc,de,unit in [(32,2000,[(0,8.24),(2,8.44),(4,8.95),(6,10.40),(8,11.26),(10,11.54),(12,11.88),(14,12.52),(16,12.90)],[2005,2017],'미국 주거용 전기 소매가격','US residential electricity price','cents/kWh'),(33,1985,[(0,60083),(5,66533),(10,70099),(15,76784),(20,84077),(25,87302),(30,94071)],[2002,2017],'세계 일평균 석유 소비량','world daily oil consumption','thousand barrels/day')]:
 slope,b,r2,step=regression(n,data);pred=[slope*(yr-base)+b for yr in ask]
 add(n,(f'{desc}의({base}년 이후 연수, {unit}) 자료 '+str(data)+f'로(a)산점도와 선형 적합성,(b)회귀선과 그래프,(c){ask[0]}년과{ask[1]}년의 모형값을 구하라.',f'For {de}, the(years since{base},{unit}) data are '+str(data)+f'. Find(a) a scatter plot and linear suitability,(b) the regression line and graph,(c) predictions for{ask[0]} and{ask[1]}.'),[('산점도는 대체로 직선적으로 상승한다.','The scatter plot shows an approximately linear upward trend.'),step,(f'연도를 경과시간으로 바꾸면 t={ask[0]-base},{ask[1]-base}이다. 첫 값은 보간, 두 번째 값은 표의 끝을 넘는 외삽이다.',f'Convert the years to elapsed times t={ask[0]-base},{ask[1]-base}. The first estimate interpolates; the second extrapolates beyond the table.')],('(b)'+m(f'y={slope:.9f}t+{b:.9f}')+f'; (c){pred[0]:.4f}, {pred[1]:.4f} {unit}.','(b)'+m(f'y={slope:.9f}t+{b:.9f}')+f'; (c){pred[0]:.4f}, {pred[1]:.4f} {unit}.'),(f'모든 자료를 사용한 회귀의 잔차합을 확인했다. R²={r2:.5f}.',f'Checked the residual sums using every data point. R²={r2:.5f}.'),list('abc'))
 regfig(n,data,lambda z,m=slope,b=b:m*z+b,de,f'years since{base}',unit)
planet=[(.387,.241),(.723,.615),(1,1),(1.523,1.881),(5.203,11.861),(9.541,29.457),(19.190,84.008),(30.086,164.784)]
pow34,logk34,r34,step=regression(34,planet,True);k34=math.exp(logk34)
add(34,('수성부터 해왕성까지의(태양거리 d:지구=1,공전주기 T:년) 자료 '+str(planet)+'로(a)거듭제곱 모형을 적합하고(b)T²∝d³라는 Kepler 제3법칙과 비교하라.','For Mercury through Neptune, the(distance d with Earth=1,period T in years) data are '+str(planet)+'. (a) Fit a power law and(b) compare with Kepler’s third law T²∝d³.'),[('T=kdᵖ의 로그를 취하여 log T=log k+p log d를 최소제곱 직선으로 적합한다. 아래 계수식의 x,y는 각각 log d,log T이다.','Take logs of T=kdᵖ and fit log T=log k+p log d by least squares. In the coefficient formula below,x and y mean log d and log T.'),step,('지수는 약1.5, 계수는 약1이므로 T²≈d³이다.','The exponent is near1.5 and the coefficient near1, so T²≈d³.')],('(a)'+m(rf'T\approx{k34:.8f}d^{{{pow34:.8f}}}')+'; (b)제3법칙을 잘 뒷받침한다.','(a)'+m(rf'T\approx{k34:.8f}d^{{{pow34:.8f}}}')+'; (b)The fit strongly supports the third law.'),('로그 자료 정규방정식의 잔차합0을 확인했다. '+f'로그 R²={r34:.8f}. 표의 반올림 때문에 정확히1,1.5가 아닐 수 있다.','Checked zero residual sums for the log-data normal equations. '+f'Log-space R²={r34:.8f}. Rounded data need not produce exactly1 and1.5.'),list('ab'))
regfig(34,planet,lambda z:k34*z**pow34,'Planetary period power fit','d','years')
a35=.7*60**.3;b35=(4/.7)**(1/.3)
add(35,('동굴 면적 A(m²)와 박쥐 종수 S의 모형은 S=0.7A⁰·³이다. (a)A=60일 때 종수,(b)S=4일 때 면적을 추정하라.','The cave-area and bat-species model is S=0.7A⁰·³ with A in m². Estimate(a) species count at A=60 and(b) area for S=4.'),[(d(r'S(60)=0.7(60)^{0.3}\approx'+f'{a35:.6f}'),d(r'S(60)=0.7(60)^{0.3}\approx'+f'{a35:.6f}')),(d(r'A=(4/0.7)^{1/0.3}\approx'+f'{b35:.6f}'),d(r'A=(4/0.7)^{1/0.3}\approx'+f'{b35:.6f}'))],(f'(a)약{a35:.2f}종(대략2~3종). (b)약{b35:.2f} m².',f'(a)About{a35:.2f} species(roughly2–3). (b)About{b35:.2f} m².'),('추정 면적을0.7A⁰·³에 넣으면4가 복원된다. 종수 모형은 연속적인 평균 추정값을 주므로 정수가 아닐 수 있다.','Substituting the estimated area into0.7A⁰·³ restores4. The model gives a continuous expected count, which need not be an integer.'),list('ab'))
islands=[(4,5),(40,9),(3459,40),(4411,39),(29418,84),(44218,76)]
p36,lk36,r36,step=regression(36,islands,True);k36=math.exp(lk36);pred36=k36*291**p36
add(36,('카리브 섬의(면적 A:mi²,파충류·양서류 종수 N) 자료 Saba(4,5),Montserrat(40,9),Puerto Rico(3459,40),Jamaica(4411,39),Hispaniola(29418,84),Cuba(44218,76)로(a)거듭제곱 모형,(b)면적291 mi²인 Dominica의 종수를 구하라.','For Caribbean islands the(area A in mi²,reptile/amphibian species N) pairs are Saba(4,5),Montserrat(40,9),Puerto Rico(3459,40),Jamaica(4411,39),Hispaniola(29418,84),Cuba(44218,76). Find(a) a power model and(b) the prediction for Dominica,area291 mi².'),[('N=kAᵖ에서 log N=log k+p log A를 적합한다. 아래 x,y는 log A,log N이다.','Fit log N=log k+p log A for N=kAᵖ. In the next formula,x,y are log A,log N.'),step,(d(rf'N(291)={k36:.8f}(291)^{{{p36:.8f}}}\approx{pred36:.5f}'),d(rf'N(291)={k36:.8f}(291)^{{{p36:.8f}}}\approx{pred36:.5f}'))],('(a)'+m(rf'N\approx{k36:.8f}A^{{{p36:.8f}}}')+f'. (b)약{pred36:.2f}, 대략{round(pred36)}종.','(a)'+m(rf'N\approx{k36:.8f}A^{{{p36:.8f}}}')+f'. (b)About{pred36:.2f}, roughly{round(pred36)} species.'),('로그 정규방정식의 잔차합0을 확인했다. '+f'로그 R²={r36:.5f}. 종수는 이 경험적 모형의 추정값이다.','Verified zero residual sums for the log normal equations. '+f'Log-space R²={r36:.5f}. The species count is an empirical-model estimate.'),list('ab'))
regfig(36,islands,lambda z:k36*z**p36,'Island area and species','mi²','species')
add(37,('세기 S>0인 점광원·힘이 모든 방향으로 균일하게 퍼진다. 반지름 r에서 강도는 S를 해당 구면 넓이로 나눈 값일 때 역제곱 법칙을 유도하라.','A point source of strength S>0 spreads uniformly in all directions. At radius r its intensity is S divided by the sphere’s surface area. Derive the inverse-square law.'),[('반지름 r의 구면 넓이는4πr²이다. 총량 S를 이 넓이에 균등 분배한다.','A sphere of radius r has surface area4πr². Spread the total strength S uniformly over that area.'),(d(r'I(r)=\frac S{4\pi r^2}=\frac{k}{r^2},\quad k=\frac S{4\pi}>0,\quad r>0'),d(r'I(r)=\frac S{4\pi r^2}=\frac{k}{r^2},\quad k=\frac S{4\pi}>0,\quad r>0'))],d(r'I(r)=k/r^2,\quad k=S/(4\pi)'),('I(r)·4πr²=S이므로 모든 반지름의 구면에서 원천의 총 세기가 보존된다.','Since I(r)·4πr²=S, the total source strength is conserved across every surrounding sphere.'))
D.save(37)
